INSERT INTO questions (source, year, subject, topic, enunciado, opcoes, gabarito, explicacao) VALUES
  ('exam', 2004, 'Português', 'Interpretação de texto', 'Para entender a atual e multifacetada crise cultural, precisamos adotar uma perspectiva extremamente ampla e analisar a situação no contexto da evolução cultural humana... (Fritjof Capra. O ponto de mutação) | A expressão "a atual e multifacetada crise cultural" (R.1), embora imprecisa, tem cada um de seus vocábulos explicitado por meio do desenvolvimento das seguintes idéias: existe uma crise cultural nos dias atuais e essa crise (degradação de valores éticos) é "multifacetada" por se estender a raças diferentes e a diferentes ecossistemas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Português', 'Interpretação de texto', 'Para entender a atual e multifacetada crise cultural, precisamos adotar uma perspectiva extremamente ampla e analisar a situação no contexto da evolução cultural humana... (Fritjof Capra. O ponto de mutação) | A relação lógica entre os dois primeiros parágrafos pode assim ser descrita: no segundo parágrafo, enuncia-se a idéia da existência de forças geradoras que, como apontam pensadores de outras épocas, foram responsáveis pelas mudanças cíclicas, elencadas no primeiro parágrafo.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Português', 'Gramática e estilo', 'Para entender a atual e multifacetada crise cultural, precisamos adotar uma perspectiva extremamente ampla e analisar a situação no contexto da evolução cultural humana... (Fritjof Capra. O ponto de mutação) | Os dados e os argumentos apresentados pelo autor asseguram a objetividade do discurso, incisivo e científico. No entanto, para se eliminarem os traços de subjetividade, seriam necessárias as seguintes alterações: retirada de "parece que" (R.3) e troca de "parecem ajustar-se" (R.10) por ajustam-se.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Português', 'Interpretação de texto', 'Para entender a atual e multifacetada crise cultural, precisamos adotar uma perspectiva extremamente ampla e analisar a situação no contexto da evolução cultural humana... (Fritjof Capra. O ponto de mutação) | As "transições" apontadas por Toynbee organizam-se diacronicamente de tal forma que são excludentes, e efetivamente ocorreram na ordem em que foram apresentadas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Português', 'Gramática e estilo', 'Para entender a atual e multifacetada crise cultural, precisamos adotar uma perspectiva extremamente ampla e analisar a situação no contexto da evolução cultural humana... (Fritjof Capra. O ponto de mutação) | A regra de acentuação gráfica ilustrada em "pólos" (R.6) não diz respeito à terminação da palavra, o que também ocorre com os vocábulos pôr (verbo) e ás (substantivo).', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Português', 'Gramática e estilo', 'Para entender a atual e multifacetada crise cultural, precisamos adotar uma perspectiva extremamente ampla e analisar a situação no contexto da evolução cultural humana... (Fritjof Capra. O ponto de mutação) | Na linha 6, observa-se que a palavra "ordem" não recebeu acento gráfico, assim como seu plural também não o receberia. Isso ocorre porque as palavras paroxítonas terminadas em -em/-ens não se acentuam, regra da qual a palavra hífens é exceção.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Português', 'Gramática e estilo', 'Para entender a atual e multifacetada crise cultural, precisamos adotar uma perspectiva extremamente ampla e analisar a situação no contexto da evolução cultural humana... (Fritjof Capra. O ponto de mutação) | As reescrituras de "a que chamou" (R.7-8) e de "de que dispomos" (R.13) como, respectivamente, que chamou de e que dispomos estão ambas de acordo com a modalidade escrita padrão da língua portuguesa e preservam o sentido original do texto.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Português', 'Gramática e estilo', 'Para entender a atual e multifacetada crise cultural, precisamos adotar uma perspectiva extremamente ampla e analisar a situação no contexto da evolução cultural humana... (Fritjof Capra. O ponto de mutação) | Na linha 9, a ligação estabelecida entre os adjetivos "notáveis" e "hipotéticos" manter-se-ia coerente com o texto, assim como seria mantida a correção gramatical da frase, caso se substituísse "mesmo que" por embora ou posto que.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Português', 'Interpretação de texto', 'Para entender a atual e multifacetada crise cultural, precisamos adotar uma perspectiva extremamente ampla e analisar a situação no contexto da evolução cultural humana... (Fritjof Capra. O ponto de mutação) | No período "Tem sido extremamente difícil entender o poder do patriarcado, por ser ele totalmente preponderante" (R.14), não se contrariaria o sentido original do texto, se a expressão grifada fosse substituída por hegemônico.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Português', 'Gramática e estilo', 'Para entender a atual e multifacetada crise cultural, precisamos adotar uma perspectiva extremamente ampla e analisar a situação no contexto da evolução cultural humana... (Fritjof Capra. O ponto de mutação) | Na linha 16, o pronome "que" exerce a mesma função sintática do termo que o antecede: predicativo do sujeito.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Português', 'Gramática e estilo', 'Para entender a atual e multifacetada crise cultural, precisamos adotar uma perspectiva extremamente ampla e analisar a situação no contexto da evolução cultural humana... (Fritjof Capra. O ponto de mutação) | Os pronomes relativos "que" (R.16) e "cujas" (R.17) têm como elemento antecedente a mesma expressão nominal.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Português', 'Gramática e estilo', 'Para entender a atual e multifacetada crise cultural, precisamos adotar uma perspectiva extremamente ampla e analisar a situação no contexto da evolução cultural humana... (Fritjof Capra. O ponto de mutação) | O pronome "tais" (R.18), sem referência própria, tem seu sentido atribuído pelo termo antecedente "universalmente aceitas" (R.17).', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Português', 'Gramática e estilo', 'Para entender a atual e multifacetada crise cultural, precisamos adotar uma perspectiva extremamente ampla e analisar a situação no contexto da evolução cultural humana... (Fritjof Capra. O ponto de mutação) | A oração "que terá profundo impacto sobre nossa vida" (R.21) poderia estar entre parênteses ou entre travessões, mas não sem as vírgulas, porque, neste caso, assumiria um caráter explicativo, o que acarretaria incoerência textual.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Português', 'Gramática e estilo', 'Para entender a atual e multifacetada crise cultural, precisamos adotar uma perspectiva extremamente ampla e analisar a situação no contexto da evolução cultural humana... (Fritjof Capra. O ponto de mutação) | Os vocábulos "dos" e "da" (R.27) provêm ambos da contração da preposição de com outro vocábulo: em "dos", com um pronome demonstrativo e, em "da", com um artigo definido.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Português', 'Gramática e estilo', 'Para entender a atual e multifacetada crise cultural, precisamos adotar uma perspectiva extremamente ampla e analisar a situação no contexto da evolução cultural humana... (Fritjof Capra. O ponto de mutação) | Mantêm-se a correção gramatical e o sentido original do texto, se o último parágrafo for reescrito do seguinte modo: Nessa ampla perspectiva de evolução cultural, cuja mudança do atual paradigma, percebe-se um processo mais vasto, com uma flutuação notavelmente regular de sistemas de valores, que pode ser apontado ao longo de toda a civilização ocidental e da maioria das outras culturas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Português', 'Gramática e estilo', 'Além de serem interdependentes, identidade e diferença partilham uma importante característica: elas são o resultado de atos de criação lingüística... (Tomaz Tadeu da Silva. Identidade e diferença) | Comprometer-se-ia o sentido original do período situado entre as linhas 3 e 6, caso se substituísse a construção na voz passiva analítica "à espera de serem reveladas ou descobertas, respeitadas ou toleradas" (R.5-6) pela passiva pronominal correspondente.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Português', 'Gramática e estilo', 'Além de serem interdependentes, identidade e diferença partilham uma importante característica: elas são o resultado de atos de criação lingüística... (Tomaz Tadeu da Silva. Identidade e diferença) | Atendendo-se às prescrições gramaticais, o segmento "Somos nós que as fabricamos" (R.8) poderia ser substituído por Somos nós quem as fabrica.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Português', 'Interpretação de texto', 'Além de serem interdependentes, identidade e diferença partilham uma importante característica: elas são o resultado de atos de criação lingüística... (Tomaz Tadeu da Silva. Identidade e diferença) | Ao final do 3.º parágrafo, mantendo-se a coerência e a coesão textuais, poderia ser acrescentado o seguinte trecho: Em outras palavras, é a própria dicotomia um dos meios pelos quais o significado é fixado.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Português', 'Interpretação de texto', 'Além de serem interdependentes, identidade e diferença partilham uma importante característica: elas são o resultado de atos de criação lingüística... (Tomaz Tadeu da Silva. Identidade e diferença) | No texto, afirma-se que os grupos sociais que estão assimetricamente situados são os que lutam para garantir o acesso aos privilégios, como evidencia o emprego das vírgulas na linha 28.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Português', 'Interpretação de texto', 'Além de serem interdependentes, identidade e diferença partilham uma importante característica: elas são o resultado de atos de criação lingüística... (Tomaz Tadeu da Silva. Identidade e diferença) | De acordo com o texto, identidade e diferença devem ser compreendidas em sua dimensão simbólica, de representação, e analisadas com base nas relações de poder.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Português', 'Interpretação de texto', 'A ética contemporânea faz grande alvoroço em torno das diferenças culturais. Sua concepção do outro tem em vista essencialmente esse tipo de diferenças... (A. Badiou. Ética: um ensaio sobre a consciência do mal) | A articulação das idéias do texto não permite a inferência de que, no passado, as diferenças culturais eram relegadas pela ética e, no momento, são alardeadas em razão dos freqüentes processos de exclusão social.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Português', 'Interpretação de texto', 'A ética contemporânea faz grande alvoroço em torno das diferenças culturais. Sua concepção do outro tem em vista essencialmente esse tipo de diferenças... (A. Badiou. Ética: um ensaio sobre a consciência do mal) | Segundo o autor do texto, os guardiães da ética contemporânea explicam toda forma de exclusão com base no determinismo cultural porque idealizam a convivência pacífica entre os povos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Português', 'Interpretação de texto', 'A ética contemporânea faz grande alvoroço em torno das diferenças culturais. Sua concepção do outro tem em vista essencialmente esse tipo de diferenças... (A. Badiou. Ética: um ensaio sobre a consciência do mal) | No último parágrafo, o autor sustenta que as diferenças, mais do que ilusórias, são falseadas pela crença de uma verdade estável, resultante do raciocínio silogístico frágil por meio do qual a corrente culturalista concebe a alteridade.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Português', 'Interpretação de texto', 'A ética contemporânea faz grande alvoroço em torno das diferenças culturais. Sua concepção do outro tem em vista essencialmente esse tipo de diferenças... (A. Badiou. Ética: um ensaio sobre a consciência do mal) | O texto é composto essencialmente por enunciados categóricos, como evidencia o emprego reiterado de formas verbais no presente do indicativo.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Português', 'Interpretação de texto', 'A ética contemporânea faz grande alvoroço em torno das diferenças culturais. Sua concepção do outro tem em vista essencialmente esse tipo de diferenças... (A. Badiou. Ética: um ensaio sobre a consciência do mal) | O texto informa que a concepção culturalista, cujos fundamentos advêm da sociologia vulgar, postula que o "outro" corresponde ao segmento selvagem, que estará sempre presente como o outro ameaçador, o bárbaro. Assim, para essa corrente, a ética prevalente é ainda a do branco colonizador.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Português', 'Gramática e estilo', 'A ética contemporânea faz grande alvoroço em torno das diferenças culturais. Sua concepção do outro tem em vista essencialmente esse tipo de diferenças... (A. Badiou. Ética: um ensaio sobre a consciência do mal) | O trecho "a fascinação (...) imaginárias" (R.12-15) suscita duas observações: há, nele, indicadores da subjetividade do autor — "fascinação verdadeiramente turística" e "inevitável bizarria" —; a inserção da vírgula após "crenças" (R.14), no lugar do ponto, seguida de alteração da inicial maiúscula, atenderia ao que prescreve a norma gramatical.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Português', 'Gramática e estilo', 'A ética contemporânea faz grande alvoroço em torno das diferenças culturais. Sua concepção do outro tem em vista essencialmente esse tipo de diferenças... (A. Badiou. Ética: um ensaio sobre a consciência do mal) | Preserva o sentido do texto original e a correção gramatical a seguinte paráfrase do período expresso entre as linhas 25 e 31: Em oposição a essas descrições superficiais, o verdadeiro pensamento deve postular que o que existe são as diferenças e toda a verdade, o vir-a-ser daquilo, que ainda não é. Logo, as diferenças são exatamente o que a verdade toda imprime e faz emergir como sem significado.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Português', 'Gramática e estilo', 'A ética contemporânea faz grande alvoroço em torno das diferenças culturais. Sua concepção do outro tem em vista essencialmente esse tipo de diferenças... (A. Badiou. Ética: um ensaio sobre a consciência do mal) | Atendendo-se à prescrição gramatical e mantendo-se a coerência com as idéias defendidas no texto, o seguinte período poderia dar continuidade ao texto III: Ou seja, a alteridade é simplesmente o que há. Existe, portanto, igual diferença entre, digamos, um camponês chinês e um funcionário norueguês tal qual entre eu e qualquer pessoa, inclusive, eu mesmo.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Português', 'Interpretação de texto', 'Além de serem interdependentes, identidade e diferença partilham uma importante característica: elas são o resultado de atos de criação lingüística... (Tomaz Tadeu da Silva. Identidade e diferença) / A ética contemporânea faz grande alvoroço em torno das diferenças culturais. Sua concepção do outro tem em vista essencialmente esse tipo de diferenças... (A. Badiou. Ética: um ensaio sobre a consciência do mal) | No texto II, o autor refuta abordagem em que se examinem a identidade e a diferença culturais dissociadas e como evidências em si, como algo estanque, dado, fixo e natural, como é o enfoque do texto III.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Português', 'Interpretação de texto', 'Além de serem interdependentes, identidade e diferença partilham uma importante característica: elas são o resultado de atos de criação lingüística... (Tomaz Tadeu da Silva. Identidade e diferença) / A ética contemporânea faz grande alvoroço em torno das diferenças culturais. Sua concepção do outro tem em vista essencialmente esse tipo de diferenças... (A. Badiou. Ética: um ensaio sobre a consciência do mal) | No texto II, o autor assume que as relações de poder permeiam a construção de identidade, ao passo que, no texto III, essas relações são sugeridas pelos julgamentos de valor ali presentes, sem que, no entanto, seja ressaltada a relação assimétrica entre os grupos sociais.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Inglês', 'Reading comprehension', 'Text I: Nobody wants to pay taxes. Almost every big corporate scandal of recent years has involved tax-dodging... (The Economist, January 2004) | In the latest revelation on 26th January, Dick Thornburgh, the man nominated to examine the fall of World-Com, delivered a report saying that, as well as a lot of other dishonest transactions of which the insolvent telecoms company is blameworthy, it also swindled the Internal Revenue Service (IRS) out of hundreds of millions of dollars in taxes by means of a tax shelter dishonestly invented by KPMG, its auditor.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Inglês', 'Reading comprehension', 'Text I: Nobody wants to pay taxes. Almost every big corporate scandal of recent years has involved tax-dodging... (The Economist, January 2004) | In the last revelation on January 26th, Dick Thornburgh, the man accredited to look into the breach of World-Com, reported that, as well as a slew of other false dealings for which the undermined telecoms companies are to be criticised, it also defrauded the Internal Revenue Service (IRS) of heaps of dollars through a tax cover created by KPMG, its accountant.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Inglês', 'Reading comprehension', 'Text I: Nobody wants to pay taxes. Almost every big corporate scandal of recent years has involved tax-dodging... (The Economist, January 2004) | In the latest revelation, Dick Thornburgh, the man in charge of evaluating the failure of World-Com, issued hearsay evidence stating that, not only many other crooked dealings are to be attributed to broken telecoms company, but that it also deprived the Internal Revenue Service (IRS) of great sums of dollars using a tax device invented by KPMG, its auditor.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Inglês', 'Reading comprehension', 'Text I: Nobody wants to pay taxes. Almost every big corporate scandal of recent years has involved tax-dodging... (The Economist, January 2004) | The expression "fret that such cases are the tip of a large iceberg" (R.13-14) means that many other similar cases have been found.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Inglês', 'Reading comprehension', 'Text I: Nobody wants to pay taxes. Almost every big corporate scandal of recent years has involved tax-dodging... (The Economist, January 2004) | The substitution of the phrase "slew of" (R.9) and the verb "boost" (R.19) by mess of and soar respectively would keep the same semantic and syntactic relations as those presented in the text.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Inglês', 'Reading comprehension', 'Text I: Nobody wants to pay taxes. Almost every big corporate scandal of recent years has involved tax-dodging... (The Economist, January 2004) | The author''s purpose is to show that governments around the world are scrabbling for scarce corporate taxes.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Inglês', 'Reading comprehension', 'Text I: Nobody wants to pay taxes. Almost every big corporate scandal of recent years has involved tax-dodging... (The Economist, January 2004) | According to the graph, from 1970 to 2001, accumulated corporate income tax receipts in North American countries displayed better results than the European ones.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Inglês', 'Reading comprehension', 'Text II: The world''s major economies are recovering and 2004 looks likely to be the best growth year for the United States since the tech bubble burst... (Newsweek, January 2004) | Blanks numbered Ø, Ù and Ú can be properly filled in with picking up, burst and sluggishness respectively.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Inglês', 'Reading comprehension', 'Text II: The world''s major economies are recovering and 2004 looks likely to be the best growth year for the United States since the tech bubble burst... (Newsweek, January 2004) | From the text, it can be inferred that the global recovery is oddly joyless in big markets, newly confident in emerging ones.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Inglês', 'Reading comprehension', 'Text II: The world''s major economies are recovering and 2004 looks likely to be the best growth year for the United States since the tech bubble burst... (Newsweek, January 2004) | According to the economic forecasters, in 2004 Southeast Asia will grow faster than Russia, which will grow more than Africa and Latin America. Venezuela will decrease 5 percent this year and Iraq will jump 60.9 percent from 2003 to 2004.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Inglês', 'Reading comprehension', 'Text III: Every year forests four times the size of Switzerland are lost because of clearing and degradation... (US State Department) | In line 6, the word "unsound" means unheard.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Inglês', 'Reading comprehension', 'Text III: Every year forests four times the size of Switzerland are lost because of clearing and degradation... (US State Department) | In line 13, the word "replenish" is synonymous with fill up.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Inglês', 'Reading comprehension', 'Text III: Every year forests four times the size of Switzerland are lost because of clearing and degradation... (US State Department) | In line 18, the phrase "an enormous stake" indicates that the United States is facing huge financial losses to keep up the sustainable management of the world''s forests.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Inglês', 'Reading comprehension', 'Text III: Every year forests four times the size of Switzerland are lost because of clearing and degradation... (US State Department) | In lines 21-22, the phrase "a vested interest in protecting" can be correctly replaced by a particular reason to protect.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Inglês', 'Reading comprehension', 'Text III: Every year forests four times the size of Switzerland are lost because of clearing and degradation... (US State Department) | The text can be associated with the following statement: The leaves of the trees are for the healing of the nations.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Inglês', 'Reading comprehension', 'Text III: Every year forests four times the size of Switzerland are lost because of clearing and degradation... (US State Department) | The main idea of the text can be correctly said to be: The problem of deforestation seems to overcome the human capability of finding a final solution to it. Lots of economic interests prevail over the unquestionable need to control the sensible use of the forests worldwide.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Inglês', 'Reading comprehension', 'Text IV: Israel is in the dock again. The International Court of Justice (ICJ) is investigating the legality of the security fence being raised on the West Bank... (Daily Telegraph, February 2004) | In line 1, the phrase "in the dock" means accused in court, and, in line 16, "underpins" can be correctly replaced by supports.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Inglês', 'Reading comprehension', 'Text IV: Israel is in the dock again. The International Court of Justice (ICJ) is investigating the legality of the security fence being raised on the West Bank... (Daily Telegraph, February 2004) | In the text, the original phrase "should have come before the Hague judges at all" (R.11) can be correctly replaced by should have come before the Hague judges in the first place.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Inglês', 'Reading comprehension', 'Text IV: Israel is in the dock again. The International Court of Justice (ICJ) is investigating the legality of the security fence being raised on the West Bank... (Daily Telegraph, February 2004) | The verbal phrase "striking at" (R.15) indicates that the UN is striving to establish the principle of territorial jurisdiction.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Inglês', 'Reading comprehension', 'Text IV: Israel is in the dock again. The International Court of Justice (ICJ) is investigating the legality of the security fence being raised on the West Bank... (Daily Telegraph, February 2004) | It is correct to conclude from the text that its author seems to favour Mr Sharon''s decision to raise a fence on the West Bank, despite the reaction of some Israel''s traditional friends.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Política Internacional', 'Política Externa Brasileira', 'Cinco paradigmas históricos foram identificados na História da Política Exterior do Brasil (Cervo e Bueno): das concessões sem barganha (1808-1828), leitura complexa do interesse nacional (1844-1889), diplomacia da agroexportação (1889-1930), nacional-desenvolvimentismo (anos 30-80), e a dança dos três paradigmas (anos 90). | A independência do Brasil integra um processo histórico mais amplo, em que há nítida interseção entre a crise do Antigo Regime (na Europa) e a crise do Antigo Sistema Colonial (nas Américas). Ao fundo, mudanças estruturais advindas da Revolução Industrial e do decorrente processo de consolidação do capitalismo tornavam anacrônicas práticas como as estabelecidas pelo sistema de exclusivo colonial.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Política Internacional', 'Política Externa Brasileira', 'Cinco paradigmas históricos foram identificados na História da Política Exterior do Brasil (Cervo e Bueno): das concessões sem barganha (1808-1828), leitura complexa do interesse nacional (1844-1889), diplomacia da agroexportação (1889-1930), nacional-desenvolvimentismo (anos 30-80), e a dança dos três paradigmas (anos 90). | O apoio ostensivo da potência hegemônica de então, a Inglaterra, interessada na crescente abertura de antigos mercados monopolizados pelas metrópoles, explica a relativa facilidade com que o ato de independência do Brasil foi reconhecido pela comunidade internacional, sem a necessidade de barganhas, como informa o texto.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Política Internacional', 'Política Externa Brasileira', 'Cinco paradigmas históricos foram identificados na História da Política Exterior do Brasil (Cervo e Bueno): das concessões sem barganha (1808-1828), leitura complexa do interesse nacional (1844-1889), diplomacia da agroexportação (1889-1930), nacional-desenvolvimentismo (anos 30-80), e a dança dos três paradigmas (anos 90). | As Tarifas Alves Branco, de 1844, cuja adoção coincide com o início do segundo paradigma da política externa brasileira, segundo a perspectiva do texto, geraram profundo desconforto nas relações Brasil-Inglaterra. Com efeito, já dominando o mercado brasileiro, aos capitais ingleses não interessava a decisão de Alves Branco de abrir o mercado nacional à livre concorrência mediante acentuada redução das alíquotas de importação.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Política Internacional', 'Política Externa Brasileira', 'Cinco paradigmas históricos foram identificados na História da Política Exterior do Brasil (Cervo e Bueno): das concessões sem barganha (1808-1828), leitura complexa do interesse nacional (1844-1889), diplomacia da agroexportação (1889-1930), nacional-desenvolvimentismo (anos 30-80), e a dança dos três paradigmas (anos 90). | O primeiro período republicano no Brasil dá início à denominada diplomacia do café, a qual, mais que simples esforço de promoção comercial, também envolvia a negociação de empréstimos, além da defesa contra acusações de cartelização e abuso de poder dominante.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Política Internacional', 'Política Externa Brasileira', 'Cinco paradigmas históricos foram identificados na História da Política Exterior do Brasil (Cervo e Bueno): das concessões sem barganha (1808-1828), leitura complexa do interesse nacional (1844-1889), diplomacia da agroexportação (1889-1930), nacional-desenvolvimentismo (anos 30-80), e a dança dos três paradigmas (anos 90). | A crescente predominância comercial, financeira e industrial dos EUA na economia brasileira, fenômeno visível já na primeira metade do século passado, ganhou redobrada intensidade após a Segunda Guerra Mundial, em especial a partir da década de 1950.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Política Internacional', 'Política Externa Brasileira', 'Cinco paradigmas históricos foram identificados na História da Política Exterior do Brasil (Cervo e Bueno): das concessões sem barganha (1808-1828), leitura complexa do interesse nacional (1844-1889), diplomacia da agroexportação (1889-1930), nacional-desenvolvimentismo (anos 30-80), e a dança dos três paradigmas (anos 90). | O paradigma do nacional-desenvolvimentismo — que, lembra o texto, se inicia na década de 30 do século XX, com Vargas — sofre descontinuidade e, em determinados momentos, dá a impressão de ser claramente abandonado. É o que acontece, por exemplo, entre 1951 e 1954, quando Getúlio Vargas, acuado pela intransigente oposição interna e por uma conjuntura internacional desfavorável, abre mão de qualquer veleidade nacionalista tanto na condução da política econômica quanto na ação externa.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Política Internacional', 'Política Externa Brasileira', 'Cinco paradigmas históricos foram identificados na História da Política Exterior do Brasil (Cervo e Bueno): das concessões sem barganha (1808-1828), leitura complexa do interesse nacional (1844-1889), diplomacia da agroexportação (1889-1930), nacional-desenvolvimentismo (anos 30-80), e a dança dos três paradigmas (anos 90). | O período governamental de Juscelino Kubitschek (1956-1961) optou por atender "às demandas do moderno desenvolvimento", com níveis relativamente baixos de endividamento e de inflação. Seus projetos de apoio à indústria de bens de consumo e ao incremento da infra-estrutura econômica do país se viabilizaram, em larga medida, pelo apoio recebido do Banco Mundial e pela extrema liberalidade com que foi tratado pelo Fundo Monetário Internacional.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Política Internacional', 'Política Externa Brasileira', 'Cinco paradigmas históricos foram identificados na História da Política Exterior do Brasil (Cervo e Bueno): das concessões sem barganha (1808-1828), leitura complexa do interesse nacional (1844-1889), diplomacia da agroexportação (1889-1930), nacional-desenvolvimentismo (anos 30-80), e a dança dos três paradigmas (anos 90). | O regime militar instaurado em 1964 reorientou a política externa brasileira, distinguindo-a profundamente daquela que a precedeu imediatamente. Daí, o alinhamento automático com a diplomacia norte-americana, procedimento que não sofreu variações significativas ao longo do período.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Política Internacional', 'Política Externa Brasileira', 'Cinco paradigmas históricos foram identificados na História da Política Exterior do Brasil (Cervo e Bueno): das concessões sem barganha (1808-1828), leitura complexa do interesse nacional (1844-1889), diplomacia da agroexportação (1889-1930), nacional-desenvolvimentismo (anos 30-80), e a dança dos três paradigmas (anos 90). | O breve governo de Fernando Collor, o primeiro eleito diretamente desde Jânio Quadros, foi marcado por um vertiginoso processo de ultra-liberalização da economia brasileira, um modelo de inserção internacional que, com menor ou igual intensidade, muitos outros países latino-americanos colocaram em prática nos anos 90 do século passado.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Política Internacional', 'Política Externa Brasileira', 'Cinco paradigmas históricos foram identificados na História da Política Exterior do Brasil (Cervo e Bueno): das concessões sem barganha (1808-1828), leitura complexa do interesse nacional (1844-1889), diplomacia da agroexportação (1889-1930), nacional-desenvolvimentismo (anos 30-80), e a dança dos três paradigmas (anos 90). | Em que pese toda a efervescência política, que teve no impeachment de Collor e seus desdobramentos o seu ápice, o governo Itamar Franco conseguiu levar adiante as reformas relativas à privatização, à desregulamentação, à abertura comercial e à regularização das relações com a comunidade financeira internacional.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Política Internacional', 'Organismos internacionais', 'A estrutura do Breve Século XX parece uma espécie de tríptico: era de catástrofe (1914-WWII), era de ouro (25-30 anos de crescimento), e nova era de decomposição. (Eric Hobsbawm. Era dos extremos) | Em 1944, representantes de 44 países — entre os quais o Brasil — reuniram-se em Bretton Woods com o objetivo de criar mecanismos que livrassem o mundo de crises globais, a exemplo da decorrente da Primeira Guerra e, em especial, da Grande Depressão dos anos 30.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Política Internacional', 'Política Internacional contemporânea', 'A estrutura do Breve Século XX parece uma espécie de tríptico: era de catástrofe (1914-WWII), era de ouro (25-30 anos de crescimento), e nova era de decomposição. (Eric Hobsbawm. Era dos extremos) | No pós-Segunda Guerra e ao longo dos anos 50 do século XX, coincidindo com a "era de ouro" mencionada no texto, o sistema de Bretton Woods funcionou sem maiores atropelos. Contudo, na década de 60, ele começou a ser fortemente pressionado em função, sobretudo, do déficit em conta-corrente que os EUA passaram a registrar, processo acelerado em larga medida pelas despesas com a guerra no Vietnã.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Política Internacional', 'Política Internacional contemporânea', 'A estrutura do Breve Século XX parece uma espécie de tríptico: era de catástrofe (1914-WWII), era de ouro (25-30 anos de crescimento), e nova era de decomposição. (Eric Hobsbawm. Era dos extremos) | Em 1973, a guerra entre árabes e judeus é um dos símbolos do fim da "era de ouro". Sofrendo os efeitos da desvalorização do dólar decidida em 1971 (governo Nixon) e ante o apoio norte-americano a Israel, os países árabes quintuplicam o preço do barril de petróleo, o que gera efeitos devastadores nas economias ocidentais.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Política Internacional', 'Comércio Internacional', 'A estrutura do Breve Século XX parece uma espécie de tríptico: era de catástrofe (1914-WWII), era de ouro (25-30 anos de crescimento), e nova era de decomposição. (Eric Hobsbawm. Era dos extremos) | Em que pese a agressiva retórica protecionista expressa por quase todos os países, as duas últimas décadas do século passado assistem à plena abertura dos mercados. Era a economia deixando de ser internacional para se tornar efetivamente mundial, o que exigiu o fim de instâncias reguladoras do comércio, como foi o caso do GATT.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Política Internacional', 'MERCOSUL e integração regional', 'A estrutura do Breve Século XX parece uma espécie de tríptico: era de catástrofe (1914-WWII), era de ouro (25-30 anos de crescimento), e nova era de decomposição. (Eric Hobsbawm. Era dos extremos) | Em uma economia que se globaliza rapidamente, a formação de blocos regionais é justificada como caminho adequado à melhor inserção internacional de seus integrantes. Nessa perspectiva, a União Européia, criada já como mercado comum pelo Tratado de Roma, de 1957, é o melhor exemplo de integração rápida, abrangente e completa que se conhece.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Política Internacional', 'MERCOSUL e integração regional', 'A partir de 1968 (II Unctad) o Brasil passou a expressar apoio mais denso aos foros multilaterais, movido pela convicção de ser essa atitude o meio de neutralizar o poder de coerção das superpotências. | A aproximação entre Argentina — governo Alfonsín — e Brasil — governo Sarney —, em meados dos anos 80 do século XX, foi o passo inicial para a constituição do futuro Mercado Comum do Sul (MERCOSUL) e se deu em um contexto de crise econômica nos dois países, recém-saídos de ditaduras militares.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Política Internacional', 'Política Externa Brasileira', 'A partir de 1968 (II Unctad) o Brasil passou a expressar apoio mais denso aos foros multilaterais, movido pela convicção de ser essa atitude o meio de neutralizar o poder de coerção das superpotências. | Ao se afastar, em 2003, das tratativas em torno da implantação da Área de Livre Comércio das Américas (ALCA), abrindo mão de co-presidir — com os EUA — a comissão negociadora do megabloco continental, o Brasil emitiu sinais claros de repulsa às práticas norte-americanas de subsídios, nomeadamente aquelas em vigor na área agrícola.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Política Internacional', 'Política Externa Brasileira', 'A partir de 1968 (II Unctad) o Brasil passou a expressar apoio mais denso aos foros multilaterais, movido pela convicção de ser essa atitude o meio de neutralizar o poder de coerção das superpotências. | A criação da Comunidade dos Países de Língua Portuguesa, que contou com ativa participação do Brasil, ocorreu em um contexto histórico amplamente favorável. Com efeito, é na década de 90 do século XX que a política brasileira para a África mais se robustece, com o sensível incremento das relações comerciais, diplomáticas e estratégicas entre o Brasil e os Estados africanos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Política Internacional', 'Política Externa Brasileira', 'A partir de 1968 (II Unctad) o Brasil passou a expressar apoio mais denso aos foros multilaterais, movido pela convicção de ser essa atitude o meio de neutralizar o poder de coerção das superpotências. | Enquanto o binômio segurança-desenvolvimento pautou, em linhas gerais, a política internacional implementada pelo regime militar, conferindo-lhe caráter mais defensivo, com a redemocratização do país, em meio ao novo cenário mundial surgido a partir de fins da década de 80 do século XX, o Brasil tratou de ampliar sua presença multilateral. Exemplos dessa estratégia seriam, entre outros, a realização da Eco-92 — no Rio de Janeiro — e a candidatura a um assento permanente no Conselho de Segurança da ONU.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Política Internacional', 'Organismos internacionais', 'A partir de 1968 (II Unctad) o Brasil passou a expressar apoio mais denso aos foros multilaterais, movido pela convicção de ser essa atitude o meio de neutralizar o poder de coerção das superpotências. | Retraída no combate às práticas protecionistas dos países e blocos economicamente mais fortes, a atuação brasileira na OMC é dura na oposição às medidas unilaterais. Já no âmbito da ONU, defende um Conselho de Segurança mais democrático, embora ainda não demonstre desconforto quanto à forma pela qual ele foi organizado, quando da criação das Nações Unidas, refletindo a realpolitik do sistema bipolar.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'História Mundial', 'Guerra Fria', 'A estrutura do Breve Século XX parece uma espécie de tríptico: era de catástrofe (1914-WWII), era de ouro (25-30 anos de crescimento), e nova era de decomposição. (Eric Hobsbawm. Era dos extremos) | Uma "curva inesperada da história", como diz o texto ao se referir à forma pela qual o século XX chegou ao fim, pode ser identificada na desintegração da União das Repúblicas Socialistas Soviéticas (URSS) e no desmonte do denominado socialismo real do Leste europeu, sacramentando a morte de um sistema bipolar de poder mundial que vigorou, com maior ou menor intensidade, desde o pós-Segunda Guerra.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'História Mundial', 'Revolução Industrial', 'A estrutura do Breve Século XX parece uma espécie de tríptico: era de catástrofe (1914-WWII), era de ouro (25-30 anos de crescimento), e nova era de decomposição. (Eric Hobsbawm. Era dos extremos) | A moderna industrialização, a partir da Revolução Industrial inglesa, desvelou uma nova realidade histórica que o texto indica como visceralmente oposta ao que existia antes, tornando obsoletas as "formas de vida e sociabilidade consolidadas durante milênios". Essa diferença manifesta-se, por exemplo, de modo "escancarado e estridente", na mudança do locus tradicional da vida social — homens e mulheres fogem ou são expulsos do mundo agrário e rural para as cidades.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'História Mundial', 'Segunda Guerra Mundial', 'A estrutura do Breve Século XX parece uma espécie de tríptico: era de catástrofe (1914-WWII), era de ouro (25-30 anos de crescimento), e nova era de decomposição. (Eric Hobsbawm. Era dos extremos) | Liberalismo e socialismo, "as duas grandes utopias da modernidade", como afirma o texto, encontraram seus limites à mesma época, ainda que por motivos e caminhos distintos. Com efeito, a crise social, política e econômica verificada nas décadas de 20 e 30 do século XX destruiu as bases do Estado liberal — substituído pelos modelos totalitários fascistas — e eliminou todo e qualquer apoio ideológico ao stalinismo soviético.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'História Mundial', 'Organismos internacionais', 'A estrutura do Breve Século XX parece uma espécie de tríptico: era de catástrofe (1914-WWII), era de ouro (25-30 anos de crescimento), e nova era de decomposição. (Eric Hobsbawm. Era dos extremos) | Quando o texto fala no direito assumindo "progressivamente a condição de um idioma universal" ao longo do século XX, certamente se refere, entre outros aspectos, ao surgimento da Liga das Nações e da Organização das Nações Unidas (ONU), ambas criadas a partir de pressupostos idealistas e razoavelmente apartadas do jogo de interesses e de manipulação do poder por parte dos Estados nacionais.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'História Mundial', 'Segunda Guerra Mundial', 'A estrutura do Breve Século XX parece uma espécie de tríptico: era de catástrofe (1914-WWII), era de ouro (25-30 anos de crescimento), e nova era de decomposição. (Eric Hobsbawm. Era dos extremos) | Exemplos de violência não faltam neste século XX, classificado também no texto como o tempo "do medo e das tragédias injustificáveis". Entre eles, podem ser destacados os artefatos nucleares e os fascismos, síntese incontrastável do que Hannah Arendt definiu como a banalização do mal.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'História Mundial', 'Primeira Guerra Mundial', 'A estrutura do Breve Século XX parece uma espécie de tríptico: era de catástrofe (1914-WWII), era de ouro (25-30 anos de crescimento), e nova era de decomposição. (Eric Hobsbawm. Era dos extremos) | Os dois grandes conflitos mundiais do século XX tiveram origens e motivações distintas. Enquanto a Grande Guerra de 1914 teve, desde o início, caráter mundial, em função sobretudo do colonialismo europeu que estendia seus tentáculos por vários continentes, a Segunda Guerra circunscreveu-se ao palco europeu, malgrado ter contado com a participação de países americanos e asiáticos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'História Mundial', 'Guerra Fria', 'A estrutura do Breve Século XX parece uma espécie de tríptico: era de catástrofe (1914-WWII), era de ouro (25-30 anos de crescimento), e nova era de decomposição. (Eric Hobsbawm. Era dos extremos) | A guerra fria assinalou a fase de confronto entre as duas superpotências que emergiram da Segunda Guerra Mundial, tendo seu clímax após o anúncio da Doutrina Truman, pela qual os Estados Unidos da América (EUA) se dispunham a apoiar os países que resistissem ao comunismo.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'História Mundial', 'Guerra Fria', 'A estrutura do Breve Século XX parece uma espécie de tríptico: era de catástrofe (1914-WWII), era de ouro (25-30 anos de crescimento), e nova era de decomposição. (Eric Hobsbawm. Era dos extremos) | O fato de a URSS de Stálin ter conseguido fabricar a bomba atômica, mas não a de hidrogênio, impediu que durante a fase de tensão mais pronunciada da guerra fria houvesse um equilíbrio entre as superpotências em termos de poder de destruição do inimigo, o que levou o governo de Moscou a manter uma atitude de prudente cautela em momentos críticos, como os ocorridos na Coréia (1951), Vietnã (1954) e Cuba (1962).', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'História do Brasil', 'República', 'A estrutura do Breve Século XX parece uma espécie de tríptico: era de catástrofe (1914-WWII), era de ouro (25-30 anos de crescimento), e nova era de decomposição. (Eric Hobsbawm. Era dos extremos) | Ainda que próximo dos EUA, especialmente em termos comerciais, o Brasil da segunda metade da década de 40 do século XX — governo Gaspar Dutra — procurou manter-se eqüidistante no cenário de polarização ideológica e de retórica demasiado agressiva da guerra fria, eximindo-se de assumir atitudes políticas que pudessem significar comprometimento ou ruptura com as superpotências.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'História Mundial', 'Oriente Médio', 'A estrutura do Breve Século XX parece uma espécie de tríptico: era de catástrofe (1914-WWII), era de ouro (25-30 anos de crescimento), e nova era de decomposição. (Eric Hobsbawm. Era dos extremos) | Exemplos marcantes de guerras localizadas — de que foi pródigo o século XX, como lembra o texto — são as ocorridas no Oriente Médio, salientando o caráter estratégico da região, na qual se mesclam motivações de ordem religiosa, geopolítica e econômica, esta diretamente ligada às abundantes reservas de petróleo lá existentes.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'História do Brasil', 'República', 'Com a queda da monarquia em 1889, o novo regime beneficiou-se dos efeitos modernizadores da abolição da escravatura. As primeiras pressões democratizantes se desencadearam na década de 20, com a crise da República Velha... (Hélgio Trindade) | Nos estertores do regime monárquico, a abolição do trabalho escravo pela Lei Áurea, ainda que tenha desagradado a uma significativa parcela da classe proprietária, não foi capaz de promover a inclusão social dos negros recém-libertados, reforçando um quadro de subalternidade dos afrodescendentes ainda visível em pleno início do século XXI.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'História do Brasil', 'República Velha', 'Com a queda da monarquia em 1889, o novo regime beneficiou-se dos efeitos modernizadores da abolição da escravatura. As primeiras pressões democratizantes se desencadearam na década de 20, com a crise da República Velha... (Hélgio Trindade) | A estrutura política vigente na República Velha preservou, como afirma o texto, a dominação oligárquica herdada do Império. Formalmente inspirado nos EUA, o modelo republicano adotado é presidencialista, mas, diferentemente de sua fonte inspiradora, mostra-se profundamente centralizado e sustentado por poucos — mas poderosos — partidos políticos nacionais.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'História do Brasil', 'República Velha', 'Com a queda da monarquia em 1889, o novo regime beneficiou-se dos efeitos modernizadores da abolição da escravatura. As primeiras pressões democratizantes se desencadearam na década de 20, com a crise da República Velha... (Hélgio Trindade) | A década de 20 do século passado assinalou o acirramento da crise que levou a República Velha ao fim. Além das cisões interoligárquicas, de que a própria Aliança Liberal seria símbolo, movimentos sociais — mesmo aqueles carentes de organicidade e de coesão doutrinária — emergem na contestação às deterioradas estruturas vigentes no país, como foi o caso do tenentismo que o texto menciona.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'História do Brasil', 'República Velha', 'Com a queda da monarquia em 1889, o novo regime beneficiou-se dos efeitos modernizadores da abolição da escravatura. As primeiras pressões democratizantes se desencadearam na década de 20, com a crise da República Velha... (Hélgio Trindade) | Paradoxalmente, a Semana de Arte Moderna de 1922 acabou por oferecer apoio ao regime oligárquico que começava a ser combatido com mais firmeza. Em que pese sua estética inovadora, até revolucionária, sua obsessão em valorizar uma cultura genuinamente brasileira e livre dos cânones europeus reforçou o conservadorismo político que tanto interessava aos donos do poder.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'História do Brasil', 'República Velha', 'Com a queda da monarquia em 1889, o novo regime beneficiou-se dos efeitos modernizadores da abolição da escravatura. As primeiras pressões democratizantes se desencadearam na década de 20, com a crise da República Velha... (Hélgio Trindade) | O que os modernistas procuravam fazer na década de 20 do século passado, isto é, uma nova forma de olhar o Brasil, estimulando a mudança da imagem que o brasileiro fazia de si mesmo e do país, ganha considerável impulso na década seguinte. É quando, entre outros intelectuais que se lançam à tarefa de interpretar o Brasil, Gilberto Freyre publica Casa Grande & Senzala, defendendo a extraordinária força da mestiçagem cultural brasileira.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'História do Brasil', 'Era Vargas', 'Com a queda da monarquia em 1889, o novo regime beneficiou-se dos efeitos modernizadores da abolição da escravatura. As primeiras pressões democratizantes se desencadearam na década de 20, com a crise da República Velha... (Hélgio Trindade) | Quando o texto se reporta aos "anos críticos" em meio à década de 30 do século passado, certamente alude ao clima de radicalização político-ideológica vivido pelo país naquela conjuntura, em larga medida resultante da mobilização de massa de dois movimentos políticos nacionais: a Ação Integralista Brasileira, de direita, e a Aliança Nacional Libertadora, de conotação esquerdista.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'História do Brasil', 'Era Vargas', 'Com a queda da monarquia em 1889, o novo regime beneficiou-se dos efeitos modernizadores da abolição da escravatura. As primeiras pressões democratizantes se desencadearam na década de 20, com a crise da República Velha... (Hélgio Trindade) | As duas tendências assumidas pela Era Vargas (1930-1945), a que o texto faz alusão, constituíram-se em indisfarçável anacronismo político em face de um contexto internacional que, fatigado pelas crises e guerras, cada vez mais abria espaço para os regimes democráticos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'História do Brasil', 'Redemocratização', 'Com a queda da monarquia em 1889, o novo regime beneficiou-se dos efeitos modernizadores da abolição da escravatura. As primeiras pressões democratizantes se desencadearam na década de 20, com a crise da República Velha... (Hélgio Trindade) | O Partido Social Democrático (PSD), a União Democrática Nacional (UDN) e o Partido Trabalhista Brasileiro (PTB) foram as principais forças político-partidárias brasileiras na denominada República liberal-conservadora, surgida com a queda da ditadura estadonovista. À medida que avançava a crise do regime, os dois primeiros partidos se aproximaram na construção de um bloco reformista, ao passo que o trabalhismo adquiria feições crescentemente conservadoras.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'História do Brasil', 'República', 'Com a queda da monarquia em 1889, o novo regime beneficiou-se dos efeitos modernizadores da abolição da escravatura. As primeiras pressões democratizantes se desencadearam na década de 20, com a crise da República Velha... (Hélgio Trindade) | Sem paralelo com qualquer outro momento vivido pela diplomacia brasileira no período republicano, a Política Externa Independente, nos primeiros anos da década de 60 do século passado, levou o Brasil a romper com suas tradições em termos de política internacional, assumindo posição de confronto com os EUA e a Europa Ocidental, de crescente rivalidade com a Argentina e de apoio explícito ao bloco socialista nos fóruns multilaterais, particularmente na ONU.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'História do Brasil', 'Regime Militar', 'Com a queda da monarquia em 1889, o novo regime beneficiou-se dos efeitos modernizadores da abolição da escravatura. As primeiras pressões democratizantes se desencadearam na década de 20, com a crise da República Velha... (Hélgio Trindade) | A ruptura institucional de 1964 foi bem mais que mero golpe militar. Ela representou a vitória — e a conquista do Estado — de um dos projetos para o país que estavam em jogo, de forma ideologicamente polarizada, especialmente ao longo do governo João Goulart. Impondo a derrota da difusa proposta reformista conduzida pelo presidente, o novo bloco de poder colocou em marcha um processo de modernização conservadora do Brasil, assentada sobre o autoritarismo político.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Geografia', 'Brasil: espaço e território', 'Diversos mapas temáticos do território brasileiro geralmente apresentam fortes contrastes inter e intra-regionais. Acerca dessas disparidades e das tendências de mudança: | A concentração espacial das atividades produtivas do país é resultado das características naturais do território. Assim, o Centro-Sul é mais propício ao desenvolvimento econômico do que o Nordeste, marcado pela semi-aridez e, portanto, fadado à estagnação econômica.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Geografia', 'Brasil: espaço e território', 'Diversos mapas temáticos do território brasileiro geralmente apresentam fortes contrastes inter e intra-regionais. Acerca dessas disparidades e das tendências de mudança: | Os contrastes nos sistemas de produção agrícola no país são bastante evidentes. As atividades da agricultura moderna coexistem com cultivos de subsistência praticados em minifúndios.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Geografia', 'Brasil: espaço e território', 'Diversos mapas temáticos do território brasileiro geralmente apresentam fortes contrastes inter e intra-regionais. Acerca dessas disparidades e das tendências de mudança: | Ainda hoje, a produção industrial tem-se firmado cada vez mais na região Sudeste, em relação às demais regiões do país, em razão da necessidade de complementaridade entre as cadeias produtivas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Geografia', 'Urbanização', 'Diversos mapas temáticos do território brasileiro geralmente apresentam fortes contrastes inter e intra-regionais. Acerca dessas disparidades e das tendências de mudança: | O país viveu uma explosão urbana derivada de seu processo de industrialização e vem diminuindo, na atualidade, a concentração espacial de sua população, em função dos fluxos migratórios em direção às áreas de fronteira econômica.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Geografia', 'Brasil: espaço e território', 'Diversos mapas temáticos do território brasileiro geralmente apresentam fortes contrastes inter e intra-regionais. Acerca dessas disparidades e das tendências de mudança: | A atual rede urbana nacional, ainda não totalmente elaborada, caracteriza-se pela integração territorial desigual e atesta a continuidade da modernização industrial vivenciada pelo país.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Geografia', 'Brasil: espaço e território', 'Diversos mapas temáticos do território brasileiro geralmente apresentam fortes contrastes inter e intra-regionais. Acerca dessas disparidades e das tendências de mudança: | Do ponto de vista social, os índices de mortalidade infantil, de esperança de vida e de saneamento básico são similares entre as diversas regiões brasileiras, embora ocorram discrepâncias na comparação entre a população rural e a urbana do país.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Geografia', 'Geopolítica', 'Determinantes políticos e econômicos que caracterizam o processo de consolidação do bloco econômico do MERCOSUL: | O MERCOSUL, orientado pela lógica da globalização, segue o modelo adotado pela União Européia, que prioriza o intercâmbio comercial.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Geografia', 'Geopolítica', 'Determinantes políticos e econômicos que caracterizam o processo de consolidação do bloco econômico do MERCOSUL: | O núcleo geoeconômico do MERCOSUL compreende concentrações industriais, áreas agrícolas modernas, portos e terminais de corredores de comércio exterior do Centro-Sul brasileiro, o que favorece a integração de cadeias produtivas dos países-membros.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Geografia', 'Geopolítica', 'Determinantes políticos e econômicos que caracterizam o processo de consolidação do bloco econômico do MERCOSUL: | A integração física da região do MERCOSUL carece ainda de infra-estrutura adequada de transportes, em razão do isolamento comercial e cultural do Brasil, em relação aos países vizinhos sul-americanos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Geografia', 'Questão ambiental', 'A Amazônia que você aprendeu na escola não existe mais. Hoje, você procura uma aldeia de índios e encontra uma fábrica ou uma fazenda moderna. | Atualmente, ações como a demarcação de áreas de preservação ambiental e a implantação de projetos de exploração econômica e ecologicamente viáveis na região comprovam a completa mudança na postura governamental e na iniciativa privada em relação ao que ocorria no passado na região amazônica.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Geografia', 'Questão ambiental', 'A Amazônia que você aprendeu na escola não existe mais. Hoje, você procura uma aldeia de índios e encontra uma fábrica ou uma fazenda moderna. | Políticas territoriais levadas a efeito pelo Estado inibiram a formação de latifúndios na região amazônica, em razão dos projetos de colonização implantados na segunda metade do século passado.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Geografia', 'Geopolítica', 'A Amazônia que você aprendeu na escola não existe mais. Hoje, você procura uma aldeia de índios e encontra uma fábrica ou uma fazenda moderna. | A instabilidade política na Amazônia internacional impulsionou projetos voltados para a segurança da faixa de fronteiras na Amazônia brasileira.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Geografia', 'Brasil: espaço e território', 'O desenvolvimento capitalista no Brasil tem promovido a reordenação territorial no campo: | Nas últimas décadas, ocorreu grande expansão na produção primária destinada à exportação, o que atesta o caráter eminentemente agrícola do país.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Geografia', 'Questão ambiental', 'O desenvolvimento capitalista no Brasil tem promovido a reordenação territorial no campo: | O crescimento agrícola do país se deu não só pela modernização tecnológica, mas também em função do aumento das terras cultivadas, com a instauração de processos erosivos acelerados e perda de solo.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Geografia', 'Brasil: espaço e território', 'O desenvolvimento capitalista no Brasil tem promovido a reordenação territorial no campo: | O progresso técnico generalizado na produção agrícola brasileira ocasionou o desaparecimento das relações não-capitalistas de produção e comercialização.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Direito Interno', 'Direito Constitucional', 'Presidente visita Benguela. O presidente inicia viagem pelo continente africano para assinar tratado comercial com a República de Benguela, país recém-criado surgido do desmembramento de outro país. (O Planeta Diário, 1º de abril de 2003) | O primeiro tratado, devidamente assinado pelo presidente da República, somente produzirá eficácia no Brasil quando ocorrer a sua incorporação à ordem jurídica interna; essa incorporação é ato subjetivamente complexo, devendo resultar da conjugação de duas vontades homogêneas: a do Poder Legislativo, mediante a edição de decreto legislativo pelo Congresso Nacional, e a do Poder Executivo, por meio de decreto editado pelo presidente da República.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Direito Internacional', 'Direito Internacional Público', 'Presidente visita Benguela. O presidente inicia viagem pelo continente africano para assinar tratado comercial com a República de Benguela, país recém-criado surgido do desmembramento de outro país. (O Planeta Diário, 1º de abril de 2003) | O segundo tratado deverá ser assinado pelo governador de estado, em nome do estado-membro da Federação que representa, pois o estado-membro é ente dotado de autonomia política e de personalidade jurídica de direito público. O presidente da República não poderá participar deste acordo, a menos que este envolva algum interesse direto da União, pois o princípio federativo impede a União de interferir em assuntos restritos aos interesses internos dos demais entes da Federação.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Direito Internacional', 'Tratados internacionais', 'Presidente visita Benguela. O presidente inicia viagem pelo continente africano para assinar tratado comercial com a República de Benguela, país recém-criado surgido do desmembramento de outro país. (O Planeta Diário, 1º de abril de 2003) | O primeiro tratado, após devidamente assinado pelas partes, é um tratado bilateral e de natureza contratual, que deverá ser interpretado de boa-fé, segundo o sentido comum atribuível aos termos no contexto e à luz de seu objeto e finalidade. Deverá ser declarado nulo se, no momento de sua conclusão, conflitar com alguma norma imperativa de direito internacional geral. [ITEM ANULADO]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Direito Internacional', 'Direito Internacional Público', 'Presidente visita Benguela. O presidente inicia viagem pelo continente africano para assinar tratado comercial com a República de Benguela, país recém-criado surgido do desmembramento de outro país. (O Planeta Diário, 1º de abril de 2003) | Considerando que o território da República de Benguela era parte de um país, que continua a existir, a referida República não deverá ficar responsável pelo pagamento de nenhuma parcela de dívida externa contraída pelo país predecessor, ainda que ambos os países tenham diversamente acordado, haja vista a existência de norma impositiva de direito internacional público a respeito dessa matéria.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Direito Internacional', 'Organismos internacionais', 'Presidente visita Benguela. O presidente inicia viagem pelo continente africano para assinar tratado comercial com a República de Benguela, país recém-criado surgido do desmembramento de outro país. (O Planeta Diário, 1º de abril de 2003) | Para que fosse aceito como país-membro da Organização das Nações Unidas (ONU), em condição de plena igualdade com os demais países-membros, a República de Benguela teria que comprovar o atendimento dos requisitos exigidos por aquela pessoa jurídica de direito público internacional para o ingresso na organização, tais como o respeito aos direitos humanos e a comprovação dos limites mínimos de população e de extensão territorial.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Direito Internacional', 'Direito Internacional Público', 'Presidente visita Benguela. O presidente inicia viagem pelo continente africano para assinar tratado comercial com a República de Benguela, país recém-criado surgido do desmembramento de outro país. (O Planeta Diário, 1º de abril de 2003) | Caso houvesse conflito entre a República de Benguela e o país predecessor, em decorrência de problemas sucessórios envolvendo, por exemplo, tratados, bens, arquivos e dívidas, tais litígios seriam passíveis de julgamento pela Corte Internacional de Justiça, situada em Haia na Holanda. Essa Corte é composta de quinze juízes, eleitos pela Assembléia Geral e pelo Conselho de Segurança das Nações Unidas, para mandatos de nove anos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Direito Internacional', 'Organismos internacionais', 'Presidente visita Benguela. O presidente inicia viagem pelo continente africano para assinar tratado comercial com a República de Benguela, país recém-criado surgido do desmembramento de outro país. (O Planeta Diário, 1º de abril de 2003) | A Organização Mundial do Comércio (OMC) é uma agência vinculada à ONU, com personalidade jurídica própria de direito internacional, criada para regular o comércio internacional. Assim, a adesão da República de Benguela à OMC deveria ser subordinada ao atendimento dos seguintes requisitos: ser membro da ONU, adequar a legislação interna aos acordos existentes no âmbito da OMC, fazer concessões nas tarifas aduaneiras e ser aceita por todos os países membros da OMC.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Direito Internacional', 'Direito Internacional Público', 'Presidente visita Benguela. O presidente inicia viagem pelo continente africano para assinar tratado comercial com a República de Benguela, país recém-criado surgido do desmembramento de outro país. (O Planeta Diário, 1º de abril de 2003) | Para que a República de Benguela pudesse firmar qualquer tratado específico com algum estado-membro da União Européia (UE), que é uma pessoa jurídica de direito público internacional, esse tratado deveria estar em harmonia com o direito comunitário da UE, visto que a ordem jurídica comunitária integra o direito interno de cada estado-membro da UE, não podendo este invocar a legislação nacional para impedir a aplicação do direito comunitário.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Direito Interno', 'Direito Constitucional', 'Presidente visita Benguela. O presidente inicia viagem pelo continente africano para assinar tratado comercial com a República de Benguela, país recém-criado surgido do desmembramento de outro país. (O Planeta Diário, 1º de abril de 2003) | De acordo com as normas jurídicas brasileiras atualmente vigentes, para que um ocupante de cargo da carreira diplomática — obrigatoriamente, portanto, de nacionalidade originária brasileira — fosse nomeado chefe de missão diplomática que o Brasil estabelecesse na República de Benguela em caráter permanente, seria necessária a edição de um decreto de nomeação pelo presidente da República, posteriormente à aprovação prévia pelo Senado Federal, por voto secreto, após argüição em sessão secreta.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Direito Interno', 'Direito Constitucional', 'Fritz, cônsul da República da Gemênia no Brasil há 5 anos. Sua empregada Helen, 17 anos, nascida na Gemênia, filha de pais brasileiros, casada no Brasil. | Hans, ainda que tenha nascido em território brasileiro, não adquiriu nacionalidade originária brasileira, não obstante o fato de o Brasil adotar, em regra, o jus soli, como critério de atribuição da nacionalidade originária. Apesar disso, Hans, de nacionalidade gemênica, tem capacidade para ser titular de direitos e deveres na ordem civil, de acordo com o direito brasileiro.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Direito Interno', 'Direito Constitucional', 'Fritz, cônsul da República da Gemênia no Brasil há 5 anos. Sua empregada Helen, 17 anos, nascida na Gemênia, filha de pais brasileiros, casada no Brasil. | Caso Helen, após a fixação de residência na República Federativa do Brasil, tenha optado pela nacionalidade brasileira, ela será considerada brasileira nata, sendo plenamente capaz para exercer por vontade própria atos da vida civil. Nessas circunstâncias, Helen não poderá jamais perder a condição de brasileira.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Direito Interno', 'Direito Constitucional', 'Fritz, cônsul da República da Gemênia no Brasil há 5 anos. Sua empregada Helen, 17 anos, nascida na Gemênia, filha de pais brasileiros, casada no Brasil. | Caso Helen não tenha optado pela nacionalidade originária brasileira nem tenha sido naturalizada em outro país, ela será considerada apátrida. Nessa hipótese, ela poderá ser extraditada, mas somente em caso de comprovado envolvimento em tráfico ilícito de entorpecentes e drogas afins, consoante o previsto na Constituição brasileira.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Direito Interno', 'Direito Civil', 'Fritz, cônsul da República da Gemênia no Brasil há 5 anos. Sua empregada Helen, 17 anos, nascida na Gemênia, filha de pais brasileiros, casada no Brasil. | Presentes o elemento objetivo e o elemento subjetivo, caracterizadores do vício do consentimento, o negócio jurídico configurado pela compra e venda do relógio é anulável em decorrência de dolo negativo, reticente ou por omissão, cabendo a Helen responder pelas perdas e danos que advierem do negócio.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Direito Internacional', 'Imunidade diplomática', 'Fritz, cônsul da República da Gemênia no Brasil há 5 anos. Sua empregada Helen, 17 anos, nascida na Gemênia, filha de pais brasileiros, casada no Brasil. | Se Helen quiser ingressar com ação judicial contra a repartição consular estrangeira, com o objetivo de pleitear os direitos trabalhistas a que considera fazer jus, a justiça trabalhista brasileira deverá declarar-se incompetente para julgar o caso, tendo em vista a imunidade de jurisdição atribuída pelo direito internacional público aos diplomatas e cônsules estrangeiros e respectivos familiares.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Economia', 'Microeconomia', 'A escolha em situação de escassez, as interações entre o governo e os mercados privados e a evolução da análise econômica são tópicos relevantes para o exame dos fenômenos econômicos. | A redução do imposto sobre operações financeiras (IOF), ao incentivar a poupança, contribui para deslocar, para cima e para a direita, a fronteira de possibilidades de produção da economia.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Economia', 'Macroeconomia', 'A escolha em situação de escassez, as interações entre o governo e os mercados privados e a evolução da análise econômica são tópicos relevantes para o exame dos fenômenos econômicos. | Economistas que se proclamam não-intervencionistas advogam a adoção de regras fixas de política econômica, tais como orçamento equilibrado e constância da taxa de crescimento do estoque monetário.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Economia', 'Teoria econômica', 'A escolha em situação de escassez, as interações entre o governo e os mercados privados e a evolução da análise econômica são tópicos relevantes para o exame dos fenômenos econômicos. | O postulado marxista de que cada estágio da história é governado por leis econômicas distintas corrobora a visão clássica, que exclui a existência de leis universais, como ilustrado no princípio malthusiano do crescimento populacional.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Economia', 'Macroeconomia', 'A escolha em situação de escassez, as interações entre o governo e os mercados privados e a evolução da análise econômica são tópicos relevantes para o exame dos fenômenos econômicos. | De acordo com a visão keynesiana, o aumento da oferta de moeda reduz as taxas de juros, o que provoca a expansão do investimento e da demanda agregada.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Economia', 'Microeconomia', 'A microeconomia estuda o comportamento individual dos agentes econômicos e constitui sólido fundamento à análise dos agregados econômicos. | O recrudescimento, na Ásia, da gripe do frango, conhecida cientificamente como influenza aviária, abre novos mercados para o produto brasileiro e desloca, para cima e para a direita, a curva de demanda por carne de frango no Brasil.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Economia', 'Microeconomia', 'A microeconomia estuda o comportamento individual dos agentes econômicos e constitui sólido fundamento à análise dos agregados econômicos. | A comercialização dos bilhetes das companhias aéreas realizada por via eletrônica, ao reduzir os custos dessas empresas, desloca, para baixo e para a direita, a curva de oferta de passagens aéreas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
